from math import ceil,sqrt
targets=['fuselage','internal_carrier','fan_motor','drive_belt','window_retainer_left','window_retainer_right','thermal_bridge_left','thermal_bridge_right','thermal_fore_shoe_left','thermal_aft_shoe_left','thermal_fore_shoe_right','thermal_aft_shoe_right']
obs=[(n,object(n),object(n).bounding_box())for n in targets]
board=[(s,s.bounding_box())for s in object('connection_board').solids() if s.bounding_box().max.Z>.135]
def possible(a,b):
 return all(getattr(a.max,k)>=getattr(b.min,k)-1e-7 and getattr(b.max,k)>=getattr(a.min,k)-1e-7 for k in ['X','Y','Z'])
def vol(s):
 if s is None:return 0.
 if isinstance(s,list):return sum(vol(x)for x in s)
 return abs(s.volume)
def check(label,cx,cy,sx,sy,height,pins,deltas):
 pose=Pos(cx,cy,.135+height/2)*Box(sx,sy,height)
 other=[];excluded=[]
 for s,b in board:
  hit=b.size.Z>10 and b.size.X<6 and b.size.Y<6 and abs((b.min.X+b.max.X)/2-cx)<.05 and abs((b.min.Y+b.max.Y)/2-cy)<.05
  if hit:excluded.append(b.max.Z)
  else:other.append(('nonmating PCB part',s,b))
 assert len(excluded)==1,(label,excluded)
 worst=0.;hit=None;count=0
 for dx,dy,dz in deltas:
  nn=max(1,ceil(sqrt(dx*dx+dy*dy+dz*dz)/.5))
  for i in range(nn+1):
   q=Pos(dx*i/nn,dy*i/nn,dz*i/nn)*pose;b=q.bounding_box()
   for name,s,sb in obs+other:
    if possible(b,sb):
     vv=vol(q.intersect(s));count+=1
     if vv>worst:worst=vv;hit=name
  pose=Pos(dx,dy,dz)*pose
 print(label,'exact overlap mm3',round(worst,7),'with',hit,'mating tip maxZ',round(max(excluded),4),'tested intersections',count)
 assert worst<1e-5
check('J9',17,15.6872,9,6.5,14,[(17,16.9572),(17,14.4172)],[(0,0,6.3),(5,0,0),(0,0,12)])
for x,y in [(-8,18.72),(-1,18.72),(6,18.72),(6,-18.72),(-8,-18.72),(-1,-18.72)]:
 check('2P'+str((x,y)),x,y,6.5,9,8.5,[(x-1.27,y),(x+1.27,y)],[(0,0,12)])
print('J9 release clearance to carrier after6.3mm',round((Pos(17,15.6872,.135+7+6.3)*Box(9,6.5,14)).distance_to(object('internal_carrier')),4))
for x,y in [(-28,24),(-28,-24),(27,24.5),(27,-24.5)]:
 gauge=Pos(x,y,49)*Cylinder(.9,50)
 ds=[(n,gauge.distance_to(s))for n,s,b in obs]
 print('hex tool',x,y,'min',min(ds,key=lambda p:p[1]))
 assert min(d for n,d in ds)>.25
